import { Component, Input, SimpleChanges } from '@angular/core';


@Component({
  selector: 'app-e22hijo',
  templateUrl: './e22hijo.component.html',
  styleUrls: ['./e22hijo.component.css']
})
export class E22hijoComponent {
  @Input() totalRecibido : number = "";


  ngOnChanges(changes: SimpleChanges): void {
    if(changes['piensoRecibido'].currentValue)
    {
      this.piensoRecibido = changes['piensoRecibido'].currentValue;
    }
  }
}
